{"component_id":"component-0316f87d8498","code":"from typing import List


def min_absolute_difference(nums: List[int], k: int) -> int:
    """Minimize |k - OR(subarray)| over all nonempty contiguous subarrays."""
    best = max(k, max(nums))
    ending: set[int] = set()
    for value in nums:
        current = {value}
        current.update(previous | value for previous in ending)
        for result in current:
            best = min(best, abs(k - result))
            if best == 0:
                return 0
        ending = current
    return best"}

{"component_id":"component-a996082c5542","code":"from functools import lru_cache


def count_beautiful_integers(low: int, high: int, k: int) -> int:
    """Count integers whose even/odd digit counts match and which are divisible by k."""
    def count_upto(bound: int) -> int:
        if bound <= 0:
            return 0
        digits = tuple(map(int, str(bound)))

        @lru_cache(None)
        def dp(pos: int, balance: int, remainder: int, tight: bool, started: bool) -> int:
            if pos == len(digits):
                return int(started and balance == 0 and remainder == 0)
            ceiling = digits[pos] if tight else 9
            total = 0
            for digit in range(ceiling + 1):
                next_tight = tight and digit == digits[pos]
                if not started and digit == 0:
                    total += dp(pos + 1, balance, remainder, next_tight, False)
                else:
                    next_balance = balance + (1 if digit % 2 == 0 else -1)
                    next_remainder = (remainder * 10 + digit) % k
                    total += dp(pos + 1, next_balance, next_remainder,
                                next_tight, True)
            return total

        return dp(0, 0, 0, True, False)

    return count_upto(high) - count_upto(low - 1)"}

{"component_id":"component-86dd47640b4a","code":"def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    """Count range values ending with s whose decimal digits are all <= limit."""
    if any(int(ch) > limit for ch in s):
        return 0

    suffix_value = int(s)
    place = 10 ** len(s)
    zero_prefix_is_valid = s[0] != "0" and suffix_value > 0

    def count_prefixes_at_most(bound: int) -> int:
        """Number of nonnegative prefix integers <= bound with allowed digits."""
        if bound < 0:
            return 0
        digits = str(bound)
        ways_tight, ways_loose = 1, 0
        for ch in digits:
            digit = int(ch)
            new_loose = ways_loose * (limit + 1)
            new_tight = ways_tight * (min(limit, digit) + 1)
            if digit > limit:
                new_loose += ways_tight * (digit - limit)
            ways_tight, ways_loose = new_tight, new_loose
        count = ways_tight + ways_loose
        # The all-zero prefix corresponds to the suffix alone. If its string
        # begins with zero, concatenation would have a leading zero instead.
        if not zero_prefix_is_valid:
            count -= 1
        return count

    def count_upto(bound: int) -> int:
        if bound < suffix_value:
            return 0
        max_prefix = (bound - suffix_value) // place
        return count_prefixes_at_most(max_prefix)

    return count_upto(finish) - count_upto(start - 1)"}

